let db, role='user', currentUserId='U-1001', page='dashboard', loginRole='user';
function loadDB(){try{db=JSON.parse(localStorage.getItem('novaxDemoDB'))||structuredClone(defaults)}catch(e){db=structuredClone(defaults)};['users','plans','deposits','withdrawals','requests','kyc','fds','notifications','audit','sports'].forEach(k=>{if(!Array.isArray(db[k]))db[k]=structuredClone(defaults[k]||[])})}
function saveDB(){localStorage.setItem('novaxDemoDB',JSON.stringify(db));updateNotifCount()}
function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function userById(id){return db.users.find(u=>u.id===id)||db.users[0]}
function currentUser(){return userById(currentUserId)}
function audit(action,detail){db.audit.unshift({id:shortId('AUD'),actor:role==='admin'?'Admin':currentUser().name,action,detail,date:today()});db.audit=db.audit.slice(0,100)}
function notify(userId,title,body){db.notifications.unshift({id:shortId('N'),userId,title,body,date:today(),read:false});}
function statusBadge(s){let c=['APPROVED','CREDITED','COMPLETED','ACTIVE','SETTLED','RESOLVED','READ'].includes(s)?'green':['PENDING_ADMIN_REVIEW','UNDER_REVIEW','CONFIRMING','SUBMITTED','MATURED','WAITING_FOR_USER'].includes(s)?'yellow':['REJECTED','FAILED','RESTRICTED','EXCEPTION','MORE_INFO_REQUIRED'].includes(s)?'red':'blue';return `<span class="badge ${c}">${escapeHtml(String(s).replaceAll('_',' '))}</span>`}
function showLogin(which='user'){loginRole=which;$('#loginScreen').classList.remove('hidden');$('#app').classList.add('hidden');$$('.login-tabs .tab').forEach(b=>b.classList.toggle('active',b.dataset.login===which));$('#loginName').value=which==='admin'?'admin@novax.demo':'alex@novax.demo';$('#loginPassword').value=which==='admin'?'admin123':'demo123'}
function enterApp(which,userId){role=which;currentUserId=userId||'U-1001';page='dashboard';$('#loginScreen').classList.add('hidden');$('#app').classList.remove('hidden');renderShell();renderPage()}
function renderShell(){
 $('#workspaceLabel').textContent=role==='admin'?'OPERATIONS WORKSPACE':'PERSONAL WORKSPACE';
 $('#currentName').textContent=role==='admin'?'NovaX Administrator':currentUser().name;
 $('#currentRole').textContent=role==='admin'?'Super Admin · Demo':'Demo account · '+currentUser().kyc.replaceAll('_',' ');
 $('#avatar').textContent=role==='admin'?'AD':currentUser().name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();
 const userNav=[['dashboard','▦','Overview'],['sports','⚽','Sports Zone'],['wallet','◈','Wallet'],['deposit','↓','Deposit crypto'],['withdraw','↑','Withdraw'],['fd','◷','Fixed deposit'],['history','↗','Transaction history'],['kyc','♙','Verification (KYC)'],['requests','☷','Request center'],['notifications','♧','Notifications'],['profile','⚙','Profile & security']];
 const adminNav=[['dashboard','▦','Overview'],['sportsadmin','⚽','Sports Management'],['users','♙','User management'],['deposits','↓','Deposit management'],['withdrawals','↑','Withdrawal approvals'],['kycadmin','✓','KYC review'],['requestsadmin','☷','Request center'],['fdadmin','◷','FD plan management'],['notifications','♧','Notifications'],['audit','≡','Audit logs']];
 $('#navigation').innerHTML=(role==='admin'?adminNav:userNav).map(([id,ico,label])=>`<button class="nav-btn ${page===id?'active':''}" data-page="${id}"><span class="nav-icon">${ico}</span><span class="nav-text">${label}</span></button>`).join('');
 $$('.nav-btn').forEach(b=>b.onclick=()=>{page=b.dataset.page;renderShell();renderPage()});
 $('#switchRole').textContent=role==='admin'?'⇄ Switch to user demo':'⇄ Switch to admin panel';
 $('#switchRole').onclick=()=>role==='admin'?enterApp('user','U-1001'):enterApp('admin');
 $('#notifButton').onclick=()=>{page='notifications';renderShell();renderPage()};
 $('#logoutBtn').onclick=()=>showLogin('user');updateNotifCount();
}
function updateNotifCount(){if(!db)return;let n=db.notifications.filter(x=>(role==='admin'||x.userId===currentUserId)&&!x.read).length;let el=$('#notifCount');if(el)el.textContent=n}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function stat(label,value,icon,foot='',color=''){return `<div class="stat-card"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value ${color}">${value}</div><div class="stat-foot">${foot}</div></div>`}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h3>${title}</h3>${action}</div>${body}</section>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">No records found</td></tr>`}</tbody></table></div>`}
function emptyTable(headers){return table(headers,`<tr><td colspan="${headers.length}" class="empty">No records yet. Create a demo request to see it here.</td></tr>`)}
function userTxRows(items){return items.map(x=>`<tr><td><b>${x.id}</b><br><small class="muted">${x.date}</small></td><td>${x.asset||x.category||'—'}</td><td>${x.amount!=null?money(x.amount,x.asset==='BTC'?6:2):'—'} ${x.asset||''}</td><td>${statusBadge(x.status)}</td><td>${x.txid?escapeHtml(x.txid):'—'}</td></tr>`).join('')}
function dashboardUser(){
 const u=currentUser(), allDep=db.deposits.filter(x=>x.userId===u.id),allWd=db.withdrawals.filter(x=>x.userId===u.id),allFd=db.fds.filter(x=>x.userId===u.id),allReq=db.requests.filter(x=>x.userId===u.id);
 const balance=u.balances.USDT||0;
 return heading('Good day, '+escapeHtml(u.name.split(' ')[0])+' 👋','Here’s your account overview and recent activity.',`<button class="secondary" data-go="deposit">↓ Deposit</button><button class="primary" data-go="withdraw">↑ Withdraw</button>`)
 +`<div class="notice">◈ <b>Demo mode:</b> balances and blockchain transactions are simulated. No real funds are moved.</div>`
 +`<div class="grid stats-grid">${stat('Total portfolio value','$'+money(balance+(u.balances.BTC||0)*67250+(u.balances.ETH||0)*3450),'◈','Estimated demo value')}${stat('Available USDT','$'+money(balance),'⇄','Available for demo actions','positive')}${stat('FD locked','$'+money(allFd.filter(x=>x.status==='ACTIVE').reduce((a,x)=>a+x.amount,0)),'◷',allFd.length+' active contract(s)')}${stat('KYC status',statusBadge(u.kyc),'✓','Account verification')}</div>`
 +`<div class="grid two-col">${panel('Your assets',`<div class="asset-list">${[['USDT','Tether USD',u.balances.USDT||0,''],['BTC','Bitcoin',u.balances.BTC||0,'btc'],['ETH','Ethereum',u.balances.ETH||0,'eth']].map(a=>`<div class="asset-row"><div class="asset-name"><div class="coin ${a[3]}">${a[0]==='USDT'?'₮':a[0]==='BTC'?'₿':'◆'}</div><div><b>${a[0]}</b><small>${a[1]}</small></div></div><div class="amount">${money(a[2],a[0]==='USDT'?2:6)}<small>${a[0]}</small></div><div class="amount">${a[0]==='USDT'?'$'+money(a[2]):a[0]==='BTC'?'$'+money(a[2]*67250):'$'+money(a[2]*3450)}<small>Est. value</small></div></div>`).join('')}</div>` ,`<button class="ghost" data-go="wallet">View wallet ↗</button>`)}${panel('Quick actions',`<div class="quick-actions"><button class="quick-action" data-go="deposit"><span>↓</span>Deposit</button><button class="quick-action" data-go="withdraw"><span>↑</span>Withdraw</button><button class="quick-action" data-go="fd"><span>◷</span>Fixed deposit</button><button class="quick-action" data-go="kyc"><span>✓</span>Verify KYC</button><button class="quick-action" data-go="requests"><span>☷</span>Get support</button><button class="quick-action" data-go="history"><span>↗</span>History</button></div>`)}</div>`
 +`<div class="grid two-col">${panel('Recent transactions',table(['REFERENCE','ASSET / TYPE','AMOUNT','STATUS','TX ID'],userTxRows([...allDep,...allWd].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5))),`<button class="ghost" data-go="history">View all</button>`)}${panel('Latest updates',notificationList(db.notifications.filter(n=>n.userId===u.id).slice(0,4)),`<button class="ghost" data-go="notifications">View inbox</button>`)}</div>`;
}
function dashboardAdmin(){
 const pending=db.withdrawals.filter(x=>x.status==='PENDING_ADMIN_REVIEW'),pendingDep=db.deposits.filter(x=>['PENDING_ADMIN_REVIEW','CONFIRMING','DETECTED','SUBMITTED'].includes(x.status)),kycs=db.kyc.filter(x=>['UNDER_REVIEW','SUBMITTED'].includes(x.status)),requests=db.requests.filter(x=>!['RESOLVED','CLOSED'].includes(x.status)),active=db.fds.filter(x=>x.status==='ACTIVE');
 return heading('Operations overview','Monitor account activity, review queues and fixed deposit operations.',`<button class="secondary" data-go="users">Manage users</button><button class="primary" data-go="notifications">Action center (${pending.length+pendingDep.length})</button>`)
 +`<div class="notice">● <b>System status:</b> Local demo is operational. Blockchain, custody, KYC provider and push delivery are not connected.</div>`
 +`<div class="grid stats-grid">${stat('Registered users',db.users.length,'♙','Demo accounts')}${stat('Pending cash flows',pendingDep.length+pending.length,'⇄',pendingDep.length+' deposits · '+pending.length+' withdrawals',(pendingDep.length+pending.length)?'negative':'')}${stat('KYC review queue',kycs.length,'✓','Waiting for reviewer')}${stat('Open user requests',requests.length,'☷','Support queue')}</div>`
 +`<div class="grid stats-grid">${stat('Deposit exceptions',db.deposits.filter(x=>['EXCEPTION','RISK_REVIEW','ON_HOLD'].includes(x.status)).length,'↓','Needs operations review')}${stat('Active FD principal','$'+money(active.reduce((a,x)=>a+x.amount,0)),'◷',active.length+' active contract(s)')}${stat('Upcoming maturities',active.filter(x=>(new Date(x.maturity)-Date.now())/86400000<7).length,'⌁','Within 7 days')}${stat('FD plans active',db.plans.filter(x=>x.status==='ACTIVE').length,'◇','10 / 20 / 30 / 60 days')}</div>`
 +`<div class="grid two-col">${panel('Deposit & withdrawal approvals',table(['TYPE / REFERENCE','USER','AMOUNT','NETWORK','STATUS','DECISION'],[...pendingDep.slice(0,4).map(x=>`<tr><td><b>↓ ${x.id}</b><br><small class="muted">Deposit</small></td><td>${escapeHtml(x.user)}</td><td>${money(x.amount,x.asset==='BTC'?6:2)} ${x.asset}</td><td>${escapeHtml(x.network)}</td><td>${statusBadge(x.status)}</td><td><div class="table-actions"><button class="danger" data-quick-reject="deposit:${x.id}">Reject</button><button class="primary" data-quick-approve="deposit:${x.id}">Accept</button></div></td></tr>`),...pending.slice(0,4).map(x=>`<tr><td><b>↑ ${x.id}</b><br><small class="muted">Withdrawal</small></td><td>${escapeHtml(x.user)}</td><td>${money(x.amount)} ${x.asset}</td><td>${escapeHtml(x.network)}</td><td>${statusBadge(x.status)}</td><td><div class="table-actions"><button class="danger" data-quick-reject="withdrawal:${x.id}">Reject</button><button class="primary" data-quick-approve="withdrawal:${x.id}">Accept / Review</button></div></td></tr>`)].join('')||`<tr><td colspan="6" class="empty">All caught up — no pending deposit or withdrawal requests.</td></tr>`),`<button class="ghost" data-go="notifications">Open action center ↗</button>`)}${panel('Recent admin activity',db.audit.slice(0,5).map(a=>`<div class="notice-item"><div class="notice-dot"></div><div><b>${escapeHtml(a.action)}</b><p>${escapeHtml(a.detail)}</p><small>${escapeHtml(a.actor)} · ${escapeHtml(a.date)}</small></div></div>`).join('')||'<div class="empty">Admin actions will appear here.</div>')}</div>`
 +`<div class="grid two-col">${panel('User account overview',table(['USER','EMAIL','KYC','STATUS','ACTION'],db.users.slice(0,4).map(u=>`<tr><td><b>${escapeHtml(u.name)}</b><br><small class="muted">${u.id}</small></td><td>${escapeHtml(u.email)}</td><td>${statusBadge(u.kyc)}</td><td>${statusBadge(u.status.toUpperCase())}</td><td><button class="secondary user-list-login" data-login-user="${u.id}">Login as user ↗</button></td></tr>`).join('')) ,`<button class="ghost" data-go="users">All users</button>`)}${panel('System health',`<div class="kv"><span>Demo frontend</span>${statusBadge('ONLINE')}</div><div class="kv"><span>Blockchain provider</span>${statusBadge('NOT CONNECTED')}</div><div class="kv"><span>Custody / signing</span>${statusBadge('NOT CONNECTED')}</div><div class="kv"><span>Push notifications</span>${statusBadge('SIMULATED')}</div><div class="kv"><span>Ledger</span><b>Browser demo ledger</b></div>`)}</div>`;
}
function walletPage(){const u=currentUser();return heading('Wallet','Asset balances, reservations and locked funds.',`<button class="primary" data-go="deposit">↓ Deposit crypto</button><button class="secondary" data-go="withdraw">↑ Withdraw</button>`)+`<div class="notice">Wallet balances in this prototype are editable demo state stored in this browser only. Do not send assets to these sample addresses.</div><div class="grid stats-grid">${stat('Available','$'+money(u.balances.USDT||0),'◈','USDT demo balance')}${stat('Withdrawal reserved','$'+money(u.reserved||0),'⇄','Pending withdrawal amount')}${stat('FD locked','$'+money(u.locked||0),'◷','Locked in active plans')}${stat('Pending deposits',db.deposits.filter(x=>x.userId===u.id&&x.status!=='CREDITED').length,'↓','Awaiting simulated confirmation')}</div>`+panel('Asset balances',`<div class="asset-list">${[['USDT',u.balances.USDT||0],['BTC',u.balances.BTC||0],['ETH',u.balances.ETH||0]].map(a=>`<div class="asset-row"><div class="asset-name"><div class="coin">${a[0]==='BTC'?'₿':a[0]==='ETH'?'◆':'₮'}</div><div><b>${a[0]}</b><small>Available balance</small></div></div><div class="amount">${money(a[1],a[0]==='USDT'?2:6)}<small>${a[0]}</small></div><div class="amount">${a[0]==='USDT'?'$'+money(a[1]):'~ $'+money(a[1]*(a[0]==='BTC'?67250:3450))}<small>Indicative value</small></div></div>`).join('')}</div>`)}
function depositPage(){return heading('Deposit crypto','Choose an asset and network to generate a demo deposit instruction.')+`<div class="grid two-col">${panel('Create deposit request',`<form id="depositForm"><div class="field"><label>Asset</label><select name="asset"><option>USDT</option><option>BTC</option><option>ETH</option></select></div><div class="field"><label>Network</label><select name="network"><option>TRC20</option><option>ERC20</option><option>Bitcoin</option></select></div><div class="field"><label>Amount to simulate</label><input name="amount" type="number" min="0.000001" step="any" required placeholder="e.g. 250"></div><div class="field"><label>Demo transaction reference (optional)</label><input name="txid" placeholder="DEMO_TX_..."></div><div class="form-actions"><button class="primary" type="submit">Create demo deposit</button></div></form><p class="form-note">SRS flow: detected → confirming → credited. This prototype simulates the status; it does not monitor a real blockchain.</p>`)}${panel('Deposit instructions',`<div class="notice warning">Demo address only — never transfer real funds.</div><div style="text-align:center;padding:12px"><div style="margin:0 auto 16px;width:108px;height:108px;background:repeating-conic-gradient(#e7f1ff 0 25%,#162237 0 50%) 50%/12px 12px;border:8px solid #e7f1ff;border-radius:8px"></div><div class="muted">Sample ${'USDT'} deposit address</div><b style="display:block;word-break:break-all;margin:10px 0">TDEMO-NOVAX-ONLY-000000</b><button class="secondary" data-copy-demo>Copy sample address</button></div><div class="kv"><span>Required confirmations</span><b>12 (simulated)</b></div><div class="kv"><span>Minimum deposit</span><b>10 USDT (demo)</b></div>`)}</div>`}
function withdrawPage(){const u=currentUser();return heading('Withdraw crypto','Submit a withdrawal request for administrator review.')+`<div class="notice">Every withdrawal enters <b>PENDING ADMIN REVIEW</b>. No blockchain broadcast occurs in this demo. Rejected requests release the reserved demo balance.</div><div class="grid two-col">${panel('Withdrawal request',`<form id="withdrawForm"><div class="field"><label>Asset</label><select name="asset"><option>USDT</option><option>BTC</option><option>ETH</option></select></div><div class="field"><label>Network</label><select name="network"><option>TRC20</option><option>ERC20</option><option>Bitcoin</option></select></div><div class="field full-field"><label>Destination address</label><input name="address" required minlength="8" placeholder="Enter destination wallet address"></div><div class="field"><label>Amount</label><input name="amount" type="number" min="0.000001" step="any" required placeholder="0.00"></div><div class="field"><label>Demo network fee</label><input value="1.00 USDT (illustrative)" disabled></div><div class="form-actions"><button class="primary" type="submit">Submit for admin approval</button></div></form><p class="form-note">Submission reserves the amount in the demo account. Admin approval/rejection is available in the separate admin dashboard.</p>`)}${panel('Balance check',`<div class="kv"><span>Available USDT</span><b>${money(u.balances.USDT||0)} USDT</b></div><div class="kv"><span>Withdrawal reserved</span><b>${money(u.reserved||0)} USDT</b></div><div class="kv"><span>KYC status</span>${statusBadge(u.kyc)}</div><div class="kv"><span>Review policy</span><b>Admin approval required</b></div><div class="kv"><span>Demo status</span>${statusBadge('SIMULATED')}</div>`)}</div>`}
function fdPage(){const u=currentUser();return heading('Fixed deposit','Select a published term and preview your indicative maturity amount.')+`<div class="notice warning">Returns are demo calculations only, not a promise or guarantee. Daily rates are configured by the demo admin. Production use requires approved product terms, risk disclosure and reward funding.</div><div class="grid plan-grid">${db.plans.map(p=>`<div class="plan-card"><div class="eyebrow">${p.status==='ACTIVE'?'AVAILABLE PLAN':'PAUSED PLAN'}</div><div class="plan-days">${p.days}<small> days</small></div><div class="plan-rate">${money(p.rate,3)}% <small style="font-size:10px">/ day</small></div><p>Asset: ${p.asset}<br>Min: ${money(p.min)} · Max: ${money(p.max)}<br>Simple, non-compounding estimate</p><button class="primary" data-subscribe-fd="${p.id}" ${p.status!=='ACTIVE'?'disabled':''}>Choose plan ↗</button></div>`).join('')}</div>`+panel('My FD contracts',table(['REFERENCE','TERM','PRINCIPAL','DAILY RATE','MATURITY','EST. REWARD','STATUS'],db.fds.filter(x=>x.userId===u.id).map(f=>`<tr><td><b>${f.id}</b></td><td>${f.days} days</td><td>${money(f.amount)} ${f.asset}</td><td>${money(f.rate,3)}%</td><td>${f.maturity}</td><td class="positive">${money(f.reward)} ${f.asset}</td><td>${statusBadge(f.status)}</td></tr>`).join('')||`<tr><td colspan="7" class="empty">No FD contracts yet. Choose one of the plans above to simulate a subscription.</td></tr>`))}
function historyPage(){const u=currentUser();let tx=[...db.deposits.filter(x=>x.userId===u.id),...db.withdrawals.filter(x=>x.userId===u.id)].sort((a,b)=>b.date.localeCompare(a.date));return heading('Transaction history','Review deposit and withdrawal references, amounts and statuses.')+panel('All transactions',`<div class="searchbar"><input id="historySearch" placeholder="Search reference, asset or status"><select id="historyType"><option value="">All transaction types</option><option value="deposit">Deposit</option><option value="withdrawal">Withdrawal</option></select></div><div id="historyTable">${table(['REFERENCE','TYPE / ASSET','AMOUNT','STATUS','TX ID'],tx.map(x=>`<tr><td><b>${x.id}</b><br><small class="muted">${x.date}</small></td><td>${db.deposits.includes(x)?'Deposit':'Withdrawal'} · ${x.asset}</td><td>${money(x.amount,x.asset==='BTC'?6:2)} ${x.asset}</td><td>${statusBadge(x.status)}</td><td>${x.txid||'—'}</td></tr>`).join(''))}</div>`)}
function kycPage(){const u=currentUser(),k=db.kyc.find(x=>x.userId===u.id);return heading('Identity verification (KYC)','Submit demo details and track review status.')+`<div class="notice">This form stores mock information only. No document is transmitted to a verification provider.</div><div class="grid two-col">${panel('Your verification status',`<div class="kv"><span>Current status</span>${statusBadge(u.kyc)}</div><div class="kv"><span>Last submission</span><b>${k?k.date:'Not submitted'}</b></div><div class="kv"><span>Reviewer note</span><b>${k?escapeHtml(k.reason||'No additional note'):'—'}</b></div>`)}${panel('Submit KYC details',`<form id="kycForm"><div class="field"><label>Full legal name</label><input name="name" required value="${escapeHtml(u.name)}"></div><div class="field"><label>Document type</label><select name="doc"><option>Aadhaar (demo only)</option><option>Passport (demo only)</option><option>Driving licence (demo only)</option></select></div><div class="field"><label>Document reference (fake/demo)</label><input name="docref" required placeholder="Enter placeholder reference"></div><div class="field"><label>Address</label><textarea name="address" required placeholder="Enter demo address"></textarea></div><div class="form-actions"><button class="primary" type="submit">Submit for review</button></div></form>`)}</div>`}
function requestsPage(){const u=currentUser();return heading('Request center','Create a support case and follow the admin response.')+`<div class="grid two-col">${panel('Create a request',`<form id="requestForm"><div class="field"><label>Category</label><select name="category"><option>Account support</option><option>KYC help</option><option>Deposit query</option><option>Withdrawal query</option><option>FD query</option><option>Technical issue</option><option>Complaint</option><option>Other</option></select></div><div class="field"><label>Subject</label><input name="subject" required maxlength="100" placeholder="Short summary"></div><div class="field"><label>Description</label><textarea name="message" required maxlength="1000" placeholder="Tell us how we can help"></textarea></div><div class="field"><label>Priority</label><select name="priority"><option>Normal</option><option>High</option><option>Urgent</option></select></div><div class="form-actions"><button class="primary" type="submit">Submit request</button></div></form>`)}${panel('My requests',table(['REFERENCE','CATEGORY','SUBJECT','STATUS','REPLY'],db.requests.filter(x=>x.userId===u.id).map(x=>`<tr><td><b>${x.id}</b></td><td>${escapeHtml(x.category)}</td><td>${escapeHtml(x.subject)}</td><td>${statusBadge(x.status)}</td><td>${x.reply?escapeHtml(x.reply):'Awaiting response'} ${x.status!=='CLOSED'?`<button class="ghost" data-reply-request="${x.id}">Reply</button>`:''}</td></tr>`).join('')||`<tr><td colspan="5" class="empty">No requests yet.</td></tr>`))}</div>`}
function notificationList(items){return items.map(n=>`<div class="notice-item"><div class="notice-dot" style="${n.read?'background:#52637c':''}"></div><div><b>${escapeHtml(n.title)}</b><p>${escapeHtml(n.body)}</p><small>${escapeHtml(n.date)} ${n.read?'· Read':'· Unread'}</small></div></div>`).join('')||'<div class="empty">No notifications.</div>'}
function notificationsPage(){
 const items=db.notifications.filter(n=>role==='admin'||n.userId===currentUserId);
 if(role!=='admin')return heading('Notifications','In-app event inbox. Push delivery is simulated in this prototype.',`<button class="secondary" id="markAllRead">Mark all read</button>`)+panel('Inbox',notificationList(items));
 const pendingDeposits=db.deposits.filter(x=>['PENDING_ADMIN_REVIEW','CONFIRMING','DETECTED','SUBMITTED'].includes(x.status));
 const pendingWithdrawals=db.withdrawals.filter(x=>x.status==='PENDING_ADMIN_REVIEW');
 const actionCard=(type,x)=>`<article class="action-ticket ${type}"><div class="ticket-top"><span class="ticket-type">${type==='deposit'?'↓ DEPOSIT REQUEST':'↑ WITHDRAWAL REQUEST'}</span>${statusBadge(x.status)}</div><div class="ticket-amount">${money(x.amount,x.asset==='BTC'?6:2)} <small>${escapeHtml(x.asset)}</small></div><div class="ticket-user"><b>${escapeHtml(x.user)}</b><span>${escapeHtml(x.id)} · ${escapeHtml(x.network||'Network pending')}</span></div><div class="ticket-meta"><span>Submitted</span><b>${escapeHtml(x.date)}</b></div>${type==='withdrawal'?`<div class="ticket-meta"><span>Destination</span><b class="ticket-address">${escapeHtml(x.address||'—')}</b></div>`:''}<div class="ticket-actions"><button class="danger" data-quick-reject="${type}:${x.id}">✕ Reject</button><button class="primary" data-quick-approve="${type}:${x.id}">✓ Accept</button></div></article>`;
 const queue=`<div class="action-center-hero"><div><span class="eyebrow">OPERATIONS · ACTION CENTER</span><h2>Requests awaiting your decision</h2><p>Review each deposit or withdrawal and notify the user automatically after a decision.</p></div><div class="queue-total"><strong>${pendingDeposits.length+pendingWithdrawals.length}</strong><span>OPEN REQUESTS</span></div></div><div class="action-summary"><div><span>↓</span><b>${pendingDeposits.length}</b><small>Pending deposits</small></div><div><span>↑</span><b>${pendingWithdrawals.length}</b><small>Pending withdrawals</small></div><div><span>✓</span><b>${db.deposits.filter(x=>x.status==='CREDITED').length}</b><small>Deposits credited</small></div><div><span>↗</span><b>${db.withdrawals.filter(x=>['COMPLETED','APPROVED'].includes(x.status)).length}</b><small>Withdrawals approved</small></div></div><div class="action-ticket-grid">${[...pendingDeposits.map(x=>actionCard('deposit',x)),...pendingWithdrawals.map(x=>actionCard('withdrawal',x))].join('')||'<div class="empty action-empty">All caught up. There are no deposit or withdrawal requests waiting for review.</div>'}</div>`;
 return heading('Admin notifications','A single operations inbox for new events and decisions that require action.',`<button class="secondary" id="markAllRead">Mark all read</button>`)+queue+panel('Event inbox',notificationList(items));
}
function profilePage(){const u=currentUser();return heading('Profile & security','Account details and demo security settings.')+`<div class="grid two-col">${panel('Profile',`<div class="kv"><span>User ID</span><b>${u.id}</b></div><div class="kv"><span>Name</span><b>${escapeHtml(u.name)}</b></div><div class="kv"><span>Email</span><b>${escapeHtml(u.email)}</b></div><div class="kv"><span>Account status</span>${statusBadge(u.status.toUpperCase())}</div><div class="kv"><span>KYC</span>${statusBadge(u.kyc)}</div>`)}${panel('Security settings',`<div class="kv"><span>Two-factor authentication</span>${statusBadge('DEMO ONLY')}</div><div class="kv"><span>Active session</span><b>This browser</b></div><div class="kv"><span>Password</span><b>Hidden</b></div><button class="secondary" id="securityAlert">Simulate security alert</button><p class="form-note">Real authentication, MFA, session controls and secure password storage require backend implementation.</p>`)}</div>`}
function usersPage(){return heading('User management','Inspect demo accounts or open the user experience as a selected account.')+panel('Registered users',`<div class="searchbar"><input id="userSearch" placeholder="Search name, email or user ID"><select id="userKycFilter"><option value="">All KYC statuses</option><option>APPROVED</option><option>UNDER_REVIEW</option><option>MORE_INFO_REQUIRED</option></select></div><div id="usersTable">${usersTableRows(db.users)}</div>`)}
function usersTableRows(items){return table(['USER','EMAIL','KYC STATUS','ACCOUNT','USDT BALANCE','ACTION'],items.map(u=>`<tr><td><b>${escapeHtml(u.name)}</b><br><small class="muted">${u.id}</small></td><td>${escapeHtml(u.email)}</td><td>${statusBadge(u.kyc)}</td><td>${statusBadge(u.status.toUpperCase())}</td><td>${money(u.balances.USDT||0)}</td><td><div class="table-actions"><button class="secondary user-list-login" data-login-user="${u.id}">Login as user ↗</button><button class="ghost" data-user-detail="${u.id}">Details</button></div></td></tr>`).join(''))}
function depositsAdmin(){const pending=db.deposits.filter(x=>['PENDING_ADMIN_REVIEW','CONFIRMING','DETECTED','SUBMITTED'].includes(x.status)).length;return heading('Deposit management','Verify incoming deposit requests, then accept to credit the demo wallet or reject with a reason.',`<button class="secondary" data-go="notifications">♧ Action center (${pending+db.withdrawals.filter(x=>x.status==='PENDING_ADMIN_REVIEW').length})</button>`)+`<div class="notice warning">Admin decision required. Accepting credits the demo balance only; this prototype does not verify a blockchain transaction or move real funds.</div>`+panel('Deposit review queue',table(['REFERENCE','USER','ASSET / NETWORK','AMOUNT','TX REFERENCE','STATUS','DECISION'],db.deposits.map(x=>`<tr><td><b>${escapeHtml(x.id)}</b><br><small class="muted">${escapeHtml(x.date)}</small></td><td>${escapeHtml(x.user)}<br><small class="muted">${escapeHtml(x.userId)}</small></td><td>${escapeHtml(x.asset)}<br><small class="muted">${escapeHtml(x.network)}</small></td><td><b>${money(x.amount,x.asset==='BTC'?6:2)} ${escapeHtml(x.asset)}</b></td><td>${escapeHtml(x.txid||'—')}</td><td>${statusBadge(x.status)}</td><td>${['PENDING_ADMIN_REVIEW','CONFIRMING','DETECTED','SUBMITTED'].includes(x.status)?`<div class="table-actions"><button class="danger" data-quick-reject="deposit:${x.id}">Reject</button><button class="primary" data-quick-approve="deposit:${x.id}">Accept</button></div>`:escapeHtml(x.reason||'Reviewed')}</td></tr>`).join('')))}
function withdrawalsAdmin(){return heading('Withdrawal approvals','Review every withdrawal before simulated broadcast. Add a reason when rejecting.')+`<div class="notice warning">Admin approval is mandatory under the SRS. Approval changes the demo status only; there is no real custody service or blockchain broadcast.</div>`+panel('Withdrawal queue',`<div class="searchbar"><input id="wdSearch" placeholder="Search reference or user"><select id="wdFilter"><option value="">All statuses</option><option>PENDING_ADMIN_REVIEW</option><option>APPROVED</option><option>REJECTED</option><option>COMPLETED</option></select></div><div id="wdTable">${withdrawalRows(db.withdrawals)}</div>`)}
function withdrawalRows(items){return table(['REFERENCE','USER','ASSET / NETWORK','DESTINATION','AMOUNT','FEE / NET','STATUS','ACTION'],items.map(x=>`<tr><td><b>${x.id}</b><br><small class="muted">${x.date}</small></td><td>${escapeHtml(x.user)}<br><small class="muted">${x.userId}</small></td><td>${x.asset}<br><small class="muted">${x.network}</small></td><td>${escapeHtml(x.address)}</td><td>${money(x.amount)} ${x.asset}</td><td>${money(x.fee)} fee<br>${money(x.net)} net</td><td>${statusBadge(x.status)}</td><td>${x.status==='PENDING_ADMIN_REVIEW'?`<div class="table-actions"><button class="danger" data-quick-reject="withdrawal:${x.id}">Reject</button><button class="primary" data-quick-approve="withdrawal:${x.id}">Accept / Review</button></div>`:escapeHtml(x.reason||'—')}</td></tr>`).join(''))}
function kycAdmin(){return heading('KYC review','Review user-submitted demo KYC cases and record a decision.')+panel('KYC queue',table(['CASE','USER','STATUS','SUBMITTED','REVIEWER ACTION'],db.kyc.map(x=>`<tr><td><b>${x.id}</b></td><td>${escapeHtml(x.user)}<br><small class="muted">${x.userId}</small></td><td>${statusBadge(x.status)}</td><td>${x.date}</td><td>${['UNDER_REVIEW','SUBMITTED','MORE_INFO_REQUIRED'].includes(x.status)?`<div class="table-actions"><button class="primary" data-kyc-decision="${x.id}" data-decision="APPROVED">Approve</button><button class="danger" data-kyc-decision="${x.id}" data-decision="REJECTED">Reject</button><button class="ghost" data-kyc-decision="${x.id}" data-decision="MORE_INFO_REQUIRED">More info</button></div>`:escapeHtml(x.reason||'Reviewed')}</td></tr>`).join('')))}
function requestsAdmin(){return heading('Request center','Triage all user requests, reply, update statuses and keep a traceable history.')+panel('All requests',table(['REFERENCE','USER','CATEGORY','SUBJECT','PRIORITY','STATUS','ACTION'],db.requests.map(x=>`<tr><td><b>${x.id}</b></td><td>${escapeHtml(x.user)}</td><td>${escapeHtml(x.category)}</td><td>${escapeHtml(x.subject)}</td><td>${statusBadge(x.priority.toUpperCase())}</td><td>${statusBadge(x.status)}</td><td><div class="table-actions"><button class="secondary" data-admin-request="${x.id}">Open</button></div></td></tr>`).join('')||`<tr><td colspan="7" class="empty">No support requests.</td></tr>`))}
function fdAdmin(){return heading('Fixed deposit management','Set explicit daily percentage rates and publish/pause demo plans.',`<button class="primary" id="newPlanBtn">＋ Configure plan</button>`)+`<div class="notice warning">Rate unit is percentage per day, simple non-compounding. Published rates affect new subscriptions only. Never present demo estimates as guaranteed returns.</div>`+panel('Published plan versions',table(['PLAN','ASSET','DURATION','DAILY RATE','MIN / MAX','STATUS','ACTION'],db.plans.map(p=>`<tr><td><b>${p.id}</b></td><td>${p.asset}</td><td>${p.days} days</td><td>${money(p.rate,3)}% / day</td><td>${money(p.min)} / ${money(p.max)}</td><td>${statusBadge(p.status)}</td><td><div class="table-actions"><button class="secondary" data-edit-plan="${p.id}">Edit rate</button><button class="ghost" data-toggle-plan="${p.id}">${p.status==='ACTIVE'?'Pause':'Publish'}</button></div></td></tr>`).join('')))+panel('FD subscriptions & settlement monitor',table(['CONTRACT','USER','PLAN','PRINCIPAL','REWARD EST.','MATURITY','STATUS','ACTION'],db.fds.map(f=>`<tr><td><b>${f.id}</b></td><td>${escapeHtml(f.user)}</td><td>${f.days} days · ${money(f.rate,3)}%</td><td>${money(f.amount)} ${f.asset}</td><td>${money(f.reward)} ${f.asset}</td><td>${f.maturity}</td><td>${statusBadge(f.status)}</td><td>${f.status==='ACTIVE'&&new Date(f.maturity)<=new Date()?`<button class="primary" data-settle-fd="${f.id}">Settle</button>`:f.status==='ACTIVE'?`<button class="ghost" data-force-mature="${f.id}">Demo mature</button>`:'—'}</td></tr>`).join('')||`<tr><td colspan="8" class="empty">FD subscriptions will appear here after a user subscribes.</td></tr>`))}
function auditPage(){return heading('Audit logs','Trace privileged actions and demo state changes.')+panel('Recent audit events',table(['EVENT','ACTOR','DETAIL','TIMESTAMP'],db.audit.map(a=>`<tr><td><b>${escapeHtml(a.action)}</b></td><td>${escapeHtml(a.actor)}</td><td>${escapeHtml(a.detail)}</td><td>${escapeHtml(a.date)}</td></tr>`).join('')||`<tr><td colspan="4" class="empty">No audit events yet.</td></tr>`))}
const SPORTS=['Cricket','Football','Table Tennis','Volleyball','Basketball','Tennis','Badminton','Kabaddi','Hockey','Baseball'];
const SPORT_EMOJI={'Cricket':'🏏','Football':'⚽','Table Tennis':'🏓','Volleyball':'🏐','Basketball':'🏀','Tennis':'🎾','Badminton':'🏸','Kabaddi':'🤼','Hockey':'🏑','Baseball':'⚾'};
function sportCard(m,admin=false){return `<article class="sport-match-card sport-${SPORTS.indexOf(m.sport)}"><div class="sport-card-top"><div class="sport-card-identity"><div class="sport-icon-3d mini"><span>${SPORT_EMOJI[m.sport]||'🏆'}</span><i></i></div><div class="sport-card-title"><b>${escapeHtml(m.sport)}</b><small>${escapeHtml(m.competition)}</small></div></div><span class="sport-status ${m.status==='LIVE'?'live':m.status==='FINISHED'?'finished':'upcoming'}">${m.status==='LIVE'?'● LIVE DEMO':m.status==='FINISHED'?'FINAL':'UPCOMING'}</span></div><div class="sport-league">${escapeHtml(m.start)}<div class="sport-teams"><div class="sport-team"><div class="team-emblem">${escapeHtml(m.home.slice(0,2).toUpperCase())}</div><b>${escapeHtml(m.home)}</b></div><div class="sport-score">${escapeHtml(m.homeScore)} <span>—</span> ${escapeHtml(m.awayScore)}<small>${escapeHtml(m.period||'Scheduled')}</small></div><div class="sport-team"><div class="team-emblem alt">${escapeHtml(m.away.slice(0,2).toUpperCase())}</div><b>${escapeHtml(m.away)}</b></div></div><div class="sport-card-foot"><span>⌖ ${escapeHtml(m.venue||'Venue TBC')}</span><span>Updated ${escapeHtml(m.updated||'Demo')}</span></div>${admin?`<button class="secondary sport-edit-btn" data-sport-edit="${m.id}">Manage match ↗</button>`:`<button class="ghost sport-detail-btn" data-sport-detail="${m.id}">Match details ↗</button>`}</article>`}
function sportsPage(){return heading('Sports Zone','Follow fixtures, scoreboards and match summaries across 10 sports.',`<span class="demo-live-pill"><i></i> DEMO FEED</span>`)+`<div class="sports-hero"><div><div class="eyebrow">NOVAX SPORTS CENTER</div><h2>Every match.<br><span>One destination.</span></h2><p>Explore sports schedules, scoreboards and match status in a clean, fast dashboard.</p><div class="sports-hero-stats"><span><b>${db.sports.length}</b> Demo fixtures</span><span><b>${db.sports.filter(m=>m.status==='LIVE').length}</b> Live-style cards</span><span><b>${SPORTS.length}</b> Sports</span></div></div><div class="sports-orbit"><div class="orbit-ring"></div><div class="orbit-ball">🏆</div><span class="orbit-label one">LIVE SCORES</span><span class="orbit-label two">MATCH CENTER</span></div></div><div class="notice warning">Sports data in this package is sample/demo data managed locally by the Admin Panel. It is not a real-time score feed. A licensed sports-data API is required for genuine live scores and fixtures.</div><section class="sports-explorer"><div class="sports-section-heading"><div><span class="eyebrow">EXPLORE BY SPORT</span><h3>Choose your game</h3><p>Tap a sport to explore its match centre.</p></div><span class="sports-count-pill">10 SPORTS</span></div><div class="sport-filter-row"><button class="sport-filter sport-filter-all active" data-sport-filter="ALL"><span class="all-sports-icon">✦</span><b>All sports</b><small>Every match</small></button>${SPORTS.map((x,i)=>`<button class="sport-filter sport-filter-card sport-filter-${i}" data-sport-filter="${x}"><span class="sport-icon-3d"><span>${SPORT_EMOJI[x]}</span><i></i></span><b>${x}</b><small>View fixtures <span>↗</span></small></button>`).join('')}</div></section><div class="sports-results-heading"><div><span class="eyebrow">MATCH CENTRE</span><h3>Fixtures & scoreboards</h3></div><span class="results-caption">DEMO DATA · NOT LIVE</span></div><div class="sports-match-grid" id="sportsMatchGrid">${db.sports.map(m=>sportCard(m)).join('')||'<div class="empty">No fixtures available.</div>'}</div><div class="sports-data-note">Scores, teams and schedules shown here are illustrative demo records. Last updated timestamps are local demo timestamps.</div>`}
function sportsAdminPage(){return heading('Sports Management','Manage demo fixtures and score updates. User-facing Sports Zone refreshes from these records.',`<button class="primary" id="addSportMatch">＋ Add fixture</button>`)+`<div class="notice warning">Admin score edits update the local demo feed only. For production, connect an authorized sports data provider and validate updates server-side.</div><div class="action-summary sports-admin-summary"><div><span>🏆</span><b>${db.sports.length}</b><small>Total fixtures</small></div><div><span>●</span><b>${db.sports.filter(m=>m.status==='LIVE').length}</b><small>Live-style status</small></div><div><span>◷</span><b>${db.sports.filter(m=>m.status==='UPCOMING').length}</b><small>Upcoming</small></div><div><span>✓</span><b>${db.sports.filter(m=>m.status==='FINISHED').length}</b><small>Finished</small></div></div><div class="sports-admin-grid">${db.sports.map(m=>sportCard(m,true)).join('')||'<div class="empty">No fixtures yet. Add a fixture to get started.</div>'}</div>`}
function sportMatchModal(id){let m=id?db.sports.find(x=>x.id===id):{id:shortId('SP'),sport:'Cricket',competition:'Demo Competition',home:'Home Team',away:'Away Team',homeScore:'0',awayScore:'0',status:'UPCOMING',period:'Scheduled',start:'Tomorrow · 18:00',venue:'Demo Venue'};if(!m)return;modal(id?'Manage sports fixture':'Add sports fixture','All changes are stored in this browser demo and shown in the Sports Zone.',`<form id="sportMatchForm"><div class="field"><label>Sport</label><select name="sport">${SPORTS.map(x=>`<option ${m.sport===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Competition / league</label><input name="competition" required maxlength="90" value="${escapeHtml(m.competition)}"></div><div class="grid two-col"><div class="field"><label>Home / first team</label><input name="home" required maxlength="70" value="${escapeHtml(m.home)}"></div><div class="field"><label>Away / second team</label><input name="away" required maxlength="70" value="${escapeHtml(m.away)}"></div></div><div class="grid two-col"><div class="field"><label>Home score</label><input name="homeScore" required maxlength="30" value="${escapeHtml(m.homeScore)}"></div><div class="field"><label>Away score</label><input name="awayScore" required maxlength="30" value="${escapeHtml(m.awayScore)}"></div></div><div class="grid two-col"><div class="field"><label>Match status</label><select name="status">${['UPCOMING','LIVE','FINISHED','POSTPONED'].map(x=>`<option ${m.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Period / game state</label><input name="period" required maxlength="60" value="${escapeHtml(m.period||'Scheduled')}"></div></div><div class="grid two-col"><div class="field"><label>Schedule display</label><input name="start" required maxlength="80" value="${escapeHtml(m.start)}"></div><div class="field"><label>Venue</label><input name="venue" maxlength="80" value="${escapeHtml(m.venue||'')}"></div></div><div class="form-actions"><button type="button" class="ghost" data-close-modal>Cancel</button>${id?`<button type="button" class="danger" id="deleteSportMatch">Delete fixture</button>`:''}<button type="submit" class="primary">Save fixture</button></div></form>`);const form=$('#sportMatchForm');form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),data={sport:f.get('sport'),competition:f.get('competition').trim(),home:f.get('home').trim(),away:f.get('away').trim(),homeScore:f.get('homeScore').trim(),awayScore:f.get('awayScore').trim(),status:f.get('status'),period:f.get('period').trim(),start:f.get('start').trim(),venue:f.get('venue').trim(),updated:today()};if(!data.home||!data.away||!data.competition)return toast('Please complete required fields');if(id){Object.assign(m,data);audit('Sports fixture updated',m.id+' · '+m.sport+' · '+m.status)}else{db.sports.unshift({id:m.id,...data});audit('Sports fixture created',m.id+' · '+m.sport)}saveDB();$('#modalRoot').innerHTML='';renderPage();toast('Sports fixture saved to demo feed')};if(id)$('#deleteSportMatch').onclick=()=>{if(!confirm('Delete this demo fixture?'))return;db.sports=db.sports.filter(x=>x.id!==id);audit('Sports fixture deleted',id);saveDB();$('#modalRoot').innerHTML='';renderPage();toast('Fixture deleted')}}
function sportDetail(id){const m=db.sports.find(x=>x.id===id);if(!m)return;modal(`${SPORT_EMOJI[m.sport]||'🏆'} ${m.sport} · Match center`,'Illustrative match details from the local demo feed.',`<div class="sport-detail-score"><div><span>${escapeHtml(m.home)}</span><strong>${escapeHtml(m.homeScore)}</strong></div><em>VS</em><div><span>${escapeHtml(m.away)}</span><strong>${escapeHtml(m.awayScore)}</strong></div></div><div class="kv"><span>Competition</span><b>${escapeHtml(m.competition)}</b></div><div class="kv"><span>Status</span>${statusBadge(m.status)}</div><div class="kv"><span>Period</span><b>${escapeHtml(m.period||'—')}</b></div><div class="kv"><span>Schedule</span><b>${escapeHtml(m.start)}</b></div><div class="kv"><span>Venue</span><b>${escapeHtml(m.venue||'—')}</b></div><div class="notice warning">Demo data only. Scores and match details are not verified live results.</div>`)}
function renderPage(){const pages=role==='admin'?{dashboard:dashboardAdmin,sportsadmin:sportsAdminPage,users:usersPage,deposits:depositsAdmin,withdrawals:withdrawalsAdmin,kycadmin:kycAdmin,requestsadmin:requestsAdmin,fdadmin:fdAdmin,notifications:notificationsPage,audit:auditPage}:{dashboard:dashboardUser,sports:sportsPage,wallet:walletPage,deposit:depositPage,withdraw:withdrawPage,fd:fdPage,history:historyPage,kyc:kycPage,requests:requestsPage,notifications:notificationsPage,profile:profilePage};const titles={dashboard:'Dashboard',sports:'Sports Zone',sportsadmin:'Sports Management',wallet:'Wallet',deposit:'Deposit crypto',withdraw:'Withdraw crypto',fd:'Fixed deposit',history:'Transaction history',kyc:'Verification',requests:'Request center',notifications:'Notifications',profile:'Profile & security',users:'User management',deposits:'Deposit management',withdrawals:'Withdrawal approvals',kycadmin:'KYC review',requestsadmin:'Request center',fdadmin:'FD plan management',audit:'Audit logs'};$('#breadcrumb').innerHTML=`Overview <span>/</span> ${titles[page]||'Dashboard'}`;$('#pageContent').innerHTML=(pages[page]||pages.dashboard)();bindPageEvents();updateNotifCount()}
function go(p){page=p;renderShell();renderPage();window.scrollTo({top:0,behavior:'smooth'})}
function modal(title,desc,content){$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-close-modal><div class="modal" role="dialog"><button class="modal-close" data-close-modal>×</button><h2>${title}</h2><p class="muted">${desc}</p>${content}</div></div>`;$$('[data-close-modal]').forEach(x=>x.onclick=e=>{if(e.target===x||x.classList.contains('modal-close'))$('#modalRoot').innerHTML=''})}
function bindPageEvents(){
 $$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
 $$('[data-login-user]').forEach(b=>b.onclick=()=>{if(role==='admin'){currentUserId=b.dataset.loginUser;enterApp('user',currentUserId);toast('Opened user dashboard in demo mode')}});
 $$('[data-review-wd]').forEach(b=>b.onclick=()=>reviewWithdrawal(b.dataset.reviewWd));
 $$('[data-subscribe-fd]').forEach(b=>b.onclick=()=>subscribeFD(b.dataset.subscribeFd));
 $$('[data-reply-request]').forEach(b=>b.onclick=()=>replyRequest(b.dataset.replyRequest));
 $$('[data-copy-demo]').forEach(b=>b.onclick=()=>{navigator.clipboard?.writeText('TDEMO-NOVAX-ONLY-000000').then(()=>toast('Sample address copied')).catch(()=>toast('Sample address: TDEMO-NOVAX-ONLY-000000'))||toast('Sample address: TDEMO-NOVAX-ONLY-000000')});
 const df=$('#depositForm');if(df)df.onsubmit=e=>{e.preventDefault();let f=new FormData(df),u=currentUser(),amount=Number(f.get('amount')),asset=f.get('asset');if(!Number.isFinite(amount)||amount<=0)return toast('Enter a valid amount');let d={id:shortId('DEP'),userId:u.id,user:u.name,asset,network:f.get('network'),amount,status:'PENDING_ADMIN_REVIEW',date:today(),txid:f.get('txid')||shortId('DEMO_TX')};db.deposits.unshift(d);notify(u.id,'Deposit request submitted',`${amount} ${asset} deposit is awaiting admin review (demo).`);audit('Deposit request created',d.id+' · '+amount+' '+asset);saveDB();toast('Deposit request sent to admin for approval');renderPage()};
 const wf=$('#withdrawForm');if(wf)wf.onsubmit=e=>{e.preventDefault();let f=new FormData(wf),u=currentUser(),asset=f.get('asset'),amount=Number(f.get('amount')),address=f.get('address').trim(),bal=Number(u.balances[asset]||0),fee=asset==='USDT'?1:0.0001;if(!address||address.length<8)return toast('Enter a valid demo destination address');if(!Number.isFinite(amount)||amount<=0)return toast('Enter a valid amount');if(amount+fee>bal)return toast(`Insufficient ${asset} available balance`);if(u.kyc!=='APPROVED')return toast('KYC approval is required for withdrawals in this demo');u.balances[asset]=bal-amount-fee;u.reserved=(u.reserved||0)+amount+fee;let w={id:shortId('WD'),userId:u.id,user:u.name,asset,network:f.get('network'),address,amount,fee,net:amount-fee,status:'PENDING_ADMIN_REVIEW',date:today(),reason:''};db.withdrawals.unshift(w);notify(u.id,'Withdrawal submitted',`${w.id} is pending admin review. No blockchain broadcast has occurred.`);audit('Withdrawal submitted',w.id+' · '+amount+' '+asset);saveDB();toast('Withdrawal sent to admin review queue');renderPage()};
 const kf=$('#kycForm');if(kf)kf.onsubmit=e=>{e.preventDefault();let f=new FormData(kf),u=currentUser();u.name=f.get('name');u.kyc='UNDER_REVIEW';let old=db.kyc.find(x=>x.userId===u.id);if(old){old.status='UNDER_REVIEW';old.date=new Date().toISOString().slice(0,10);old.reason=''}else db.kyc.unshift({id:shortId('KYC'),userId:u.id,user:u.name,status:'UNDER_REVIEW',date:new Date().toISOString().slice(0,10),reason:''});notify(u.id,'KYC submitted','Your demo verification is under review.');audit('KYC submitted',u.id);saveDB();toast('KYC demo submission received');renderPage()};
 const rf=$('#requestForm');if(rf)rf.onsubmit=e=>{e.preventDefault();let f=new FormData(rf),u=currentUser(),r={id:shortId('REQ'),userId:u.id,user:u.name,category:f.get('category'),subject:f.get('subject'),message:f.get('message'),status:'SUBMITTED',priority:f.get('priority'),date:today(),reply:''};db.requests.unshift(r);notify(u.id,'Support request received',`${r.id}: ${r.subject}`);audit('Support request created',r.id+' · '+r.subject);saveDB();toast('Request submitted to admin center');renderPage()};
 const us=$('#userSearch'),uk=$('#userKycFilter');if(us)us.oninput=filterUsers;if(uk)uk.onchange=filterUsers;
 const ws=$('#wdSearch'),wfilt=$('#wdFilter');if(ws)ws.oninput=filterWithdrawals;if(wfilt)wfilt.onchange=filterWithdrawals;
 const hs=$('#historySearch'),ht=$('#historyType');if(hs)hs.oninput=filterHistory;if(ht)ht.onchange=filterHistory;
 const mark=$('#markAllRead');if(mark)mark.onclick=()=>{db.notifications.filter(n=>role==='admin'||n.userId===currentUserId).forEach(n=>n.read=true);saveDB();renderPage();toast('Notifications marked as read')};
 const alert=$('#securityAlert');if(alert)alert.onclick=()=>{notify(currentUserId,'Security alert','Demo security event: a new session action was simulated.');audit('Security alert simulated',currentUserId);saveDB();toast('Security notification added')};
 const np=$('#newPlanBtn');if(np)np.onclick=()=>planModal();
 const addSport=$('#addSportMatch');if(addSport)addSport.onclick=()=>sportMatchModal();
 $$('[data-sport-edit]').forEach(b=>b.onclick=()=>sportMatchModal(b.dataset.sportEdit));
 $$('[data-sport-detail]').forEach(b=>b.onclick=()=>sportDetail(b.dataset.sportDetail));
 $$('[data-sport-filter]').forEach(b=>b.onclick=()=>{ $$('.sport-filter').forEach(x=>x.classList.toggle('active',x===b)); const selected=b.dataset.sportFilter; const list=db.sports.filter(m=>selected==='ALL'||m.sport===selected); const grid=$('#sportsMatchGrid');if(grid)grid.innerHTML=list.map(m=>sportCard(m)).join('')||'<div class="empty">No fixtures found for this sport.</div>';bindPageEvents() });
 $$('[data-quick-approve]').forEach(b=>b.onclick=()=>{const [type,id]=b.dataset.quickApprove.split(':');if(type==='deposit')decideDeposit(id,'ACCEPTED');else if(type==='withdrawal')reviewWithdrawal(id)});
 $$('[data-quick-reject]').forEach(b=>b.onclick=()=>{const [type,id]=b.dataset.quickReject.split(':');if(type==='deposit')decideDeposit(id,'REJECTED');else if(type==='withdrawal')rejectWithdrawal(id)});
 $$('[data-credit-deposit]').forEach(b=>b.onclick=()=>decideDeposit(b.dataset.creditDeposit,'ACCEPTED'));
 $$('[data-deposit-hold]').forEach(b=>b.onclick=()=>{let d=db.deposits.find(x=>x.id===b.dataset.depositHold);if(d){d.status='ON_HOLD';notify(d.userId,'Deposit on hold',`${d.id} requires demo operations review.`);audit('Deposit placed on hold',d.id);saveDB();renderPage();toast('Deposit placed on hold')}});
 $$('[data-kyc-decision]').forEach(b=>b.onclick=()=>kycDecision(b.dataset.kycDecision,b.dataset.decision));
 $$('[data-admin-request]').forEach(b=>b.onclick=()=>adminRequest(b.dataset.adminRequest));
 $$('[data-edit-plan]').forEach(b=>b.onclick=()=>planModal(b.dataset.editPlan));
 $$('[data-toggle-plan]').forEach(b=>b.onclick=()=>togglePlan(b.dataset.togglePlan));
 $$('[data-settle-fd]').forEach(b=>b.onclick=()=>settleFD(b.dataset.settleFd));
 $$('[data-force-mature]').forEach(b=>b.onclick=()=>{let f=db.fds.find(x=>x.id===b.dataset.forceMature);if(f){f.maturity=new Date(Date.now()-1000).toISOString().slice(0,10);audit('FD demo maturity advanced',f.id);saveDB();renderPage();toast('Maturity date advanced for demo testing')}});
 $$('[data-user-detail]').forEach(b=>{let u=userById(b.dataset.userDetail);modal('User account details',u.id,`<div class="kv"><span>Name</span><b>${escapeHtml(u.name)}</b></div><div class="kv"><span>Email</span><b>${escapeHtml(u.email)}</b></div><div class="kv"><span>KYC</span>${statusBadge(u.kyc)}</div><div class="kv"><span>Account status</span>${statusBadge(u.status.toUpperCase())}</div><div class="kv"><span>USDT available</span><b>${money(u.balances.USDT||0)}</b></div><div class="form-actions"><button class="primary" id="detailLogin">Login as user</button></div>`);$('#detailLogin').onclick=()=>enterApp('user',u.id)});
}
function filterUsers(){let q=($('#userSearch')?.value||'').toLowerCase(),k=$('#userKycFilter')?.value||'';$('#usersTable').innerHTML=usersTableRows(db.users.filter(u=>(u.name+' '+u.email+' '+u.id).toLowerCase().includes(q)&&(!k||u.kyc===k)));bindPageEvents()}
function filterWithdrawals(){let q=($('#wdSearch')?.value||'').toLowerCase(),s=$('#wdFilter')?.value||'';$('#wdTable').innerHTML=withdrawalRows(db.withdrawals.filter(x=>(x.id+' '+x.user).toLowerCase().includes(q)&&(!s||x.status===s)));bindPageEvents()}
function filterHistory(){let q=($('#historySearch')?.value||'').toLowerCase(),t=$('#historyType')?.value||'',u=currentUser(),items=[...db.deposits.filter(x=>x.userId===u.id).map(x=>({...x,type:'deposit'})),...db.withdrawals.filter(x=>x.userId===u.id).map(x=>({...x,type:'withdrawal'}))].filter(x=>(x.id+' '+x.asset+' '+x.status).toLowerCase().includes(q)&&(!t||x.type===t));$('#historyTable').innerHTML=table(['REFERENCE','TYPE / ASSET','AMOUNT','STATUS','TX ID'],items.map(x=>`<tr><td><b>${x.id}</b><br><small class="muted">${x.date}</small></td><td>${x.type} · ${x.asset}</td><td>${money(x.amount)} ${x.asset}</td><td>${statusBadge(x.status)}</td><td>${x.txid||'—'}</td></tr>`).join(''))}
function rejectWithdrawal(id){const w=db.withdrawals.find(x=>x.id===id);if(!w||w.status!=='PENDING_ADMIN_REVIEW')return toast('Withdrawal request has already been reviewed');modal('Reject withdrawal · '+w.id,'Confirm the request and provide a clear rejection reason. Reserved demo funds will be released.',`<div class="kv"><span>User</span><b>${escapeHtml(w.user)} (${escapeHtml(w.userId)})</b></div><div class="kv"><span>Asset / network</span><b>${escapeHtml(w.asset)} · ${escapeHtml(w.network)}</b></div><div class="kv"><span>Requested amount</span><b>${money(w.amount)} ${escapeHtml(w.asset)}</b></div><div class="kv"><span>Destination</span><b>${escapeHtml(w.address||'—')}</b></div><div class="field"><label>Reason for rejection *</label><textarea id="wdRejectReason" required placeholder="Explain why this withdrawal is rejected"></textarea></div><div class="form-actions"><button class="ghost" data-close-modal>Cancel</button><button class="danger" id="confirmWithdrawalReject">✕ Reject & release funds</button></div>`);$('#confirmWithdrawalReject').onclick=()=>{if(w.status!=='PENDING_ADMIN_REVIEW')return toast('Withdrawal request has already been reviewed');const reason=$('#wdRejectReason').value.trim();if(!reason)return toast('Enter a rejection reason');const u=userById(w.userId);u.balances[w.asset]=(u.balances[w.asset]||0)+w.amount+w.fee;u.reserved=Math.max(0,(u.reserved||0)-w.amount-w.fee);w.status='REJECTED';w.reason=reason;w.reviewedAt=today();notify(w.userId,'Withdrawal rejected',`${w.id} was rejected. Reserved demo balance released. Reason: ${reason}`);audit('Withdrawal rejected',w.id+' · '+reason);saveDB();$('#modalRoot').innerHTML='';renderPage();toast('Withdrawal rejected · demo funds released')}}
function decideDeposit(id,decision){const d=db.deposits.find(x=>x.id===id);if(!d||!['PENDING_ADMIN_REVIEW','CONFIRMING','DETECTED','SUBMITTED'].includes(d.status))return toast('Deposit request has already been reviewed');const u=userById(d.userId);if(decision==='ACCEPTED'){modal('Accept deposit · '+d.id,'Confirm the request details before crediting the simulated user balance.',`<div class="kv"><span>User</span><b>${escapeHtml(d.user)} (${escapeHtml(d.userId)})</b></div><div class="kv"><span>Asset / network</span><b>${escapeHtml(d.asset)} · ${escapeHtml(d.network)}</b></div><div class="kv"><span>Amount to credit</span><b class="positive">${money(d.amount,d.asset==='BTC'?6:2)} ${escapeHtml(d.asset)}</b></div><div class="kv"><span>Transaction reference</span><b>${escapeHtml(d.txid||'—')}</b></div><div class="notice warning">This only updates the demo ledger. Verify real on-chain confirmations on a secure backend before production crediting.</div><div class="field"><label>Admin note (optional)</label><textarea id="depDecisionReason" placeholder="Add a reviewer note"></textarea></div><div class="form-actions"><button class="ghost" data-close-modal>Cancel</button><button class="primary" id="confirmDepositAccept">✓ Accept & credit demo balance</button></div>`);$('#confirmDepositAccept').onclick=()=>{if(!['PENDING_ADMIN_REVIEW','CONFIRMING','DETECTED','SUBMITTED'].includes(d.status))return toast('Deposit request has already been reviewed');d.status='CREDITED';d.reason=$('#depDecisionReason').value.trim()||'Accepted by admin';d.reviewedAt=today();u.balances[d.asset]=(u.balances[d.asset]||0)+d.amount;notify(d.userId,'Deposit accepted',`${d.id} was accepted by admin and ${money(d.amount,d.asset==='BTC'?6:2)} ${d.asset} was credited to your demo balance.${d.reason?' Note: '+d.reason:''}`);audit('Deposit accepted and credited',d.id+' · '+d.amount+' '+d.asset+' · '+d.reason);saveDB();$('#modalRoot').innerHTML='';renderPage();toast('Deposit accepted · demo balance credited')}}else{modal('Reject deposit · '+d.id,'A rejection reason is required. The user will receive an in-app notification.',`<div class="kv"><span>User</span><b>${escapeHtml(d.user)} (${escapeHtml(d.userId)})</b></div><div class="kv"><span>Deposit amount</span><b>${money(d.amount,d.asset==='BTC'?6:2)} ${escapeHtml(d.asset)}</b></div><div class="kv"><span>Transaction reference</span><b>${escapeHtml(d.txid||'—')}</b></div><div class="field"><label>Reason for rejection *</label><textarea id="depRejectReason" required placeholder="Explain why this deposit is rejected"></textarea></div><div class="form-actions"><button class="ghost" data-close-modal>Cancel</button><button class="danger" id="confirmDepositReject">✕ Reject deposit</button></div>`);$('#confirmDepositReject').onclick=()=>{if(!['PENDING_ADMIN_REVIEW','CONFIRMING','DETECTED','SUBMITTED'].includes(d.status))return toast('Deposit request has already been reviewed');const reason=$('#depRejectReason').value.trim();if(!reason)return toast('Enter a rejection reason');d.status='REJECTED';d.reason=reason;d.reviewedAt=today();notify(d.userId,'Deposit rejected',`${d.id} was rejected by admin. Reason: ${reason}`);audit('Deposit rejected',d.id+' · '+reason);saveDB();$('#modalRoot').innerHTML='';renderPage();toast('Deposit rejected and user notified')}}}
function reviewWithdrawal(id){const w=db.withdrawals.find(x=>x.id===id);if(!w)return;const u=userById(w.userId);modal('Review withdrawal · '+w.id,'Check user, destination, network, amount and fee before making a decision.',`<div class="kv"><span>User</span><b>${escapeHtml(w.user)} (${w.userId})</b></div><div class="kv"><span>KYC</span>${statusBadge(u.kyc)}</div><div class="kv"><span>Asset / network</span><b>${w.asset} · ${w.network}</b></div><div class="kv"><span>Destination</span><b>${escapeHtml(w.address)}</b></div><div class="kv"><span>Requested amount</span><b>${money(w.amount)} ${w.asset}</b></div><div class="kv"><span>Fee / net receive</span><b>${money(w.fee)} / ${money(w.net)} ${w.asset}</b></div><div class="field"><label>Decision reason / audit note</label><textarea id="wdReason" placeholder="Required for rejection; optional for approval"></textarea></div><div class="form-actions"><button class="danger" id="rejectWd">Reject & release funds</button><button class="primary" id="approveWd">Approve demo withdrawal</button></div>`);$('#approveWd').onclick=()=>{if(w.status!=='PENDING_ADMIN_REVIEW')return toast('Request already reviewed');w.status='APPROVED';w.reason=$('#wdReason').value.trim()||'Approved by admin';u.reserved=Math.max(0,(u.reserved||0)-w.amount-w.fee);w.status='COMPLETED';w.txid=shortId('DEMO_TX');notify(w.userId,'Withdrawal approved',`${w.id} was approved and marked completed in demo mode. No on-chain transfer occurred.`);audit('Withdrawal approved (demo only)',w.id+' · '+w.reason);saveDB();$('#modalRoot').innerHTML='';renderPage();toast('Approved and completed in demo ledger only')};$('#rejectWd').onclick=()=>{if(w.status!=='PENDING_ADMIN_REVIEW')return toast('Request already reviewed');let reason=$('#wdReason').value.trim();if(!reason)return toast('Enter a rejection reason');u.balances[w.asset]=(u.balances[w.asset]||0)+w.amount+w.fee;u.reserved=Math.max(0,(u.reserved||0)-w.amount-w.fee);w.status='REJECTED';w.reason=reason;notify(w.userId,'Withdrawal rejected',`${w.id} was rejected. Reserved demo balance released. Reason: ${reason}`);audit('Withdrawal rejected',w.id+' · '+reason);saveDB();$('#modalRoot').innerHTML='';renderPage();toast('Rejected; demo balance released')}}
function kycDecision(id,decision){let k=db.kyc.find(x=>x.id===id);if(!k)return;let reason=prompt(decision==='APPROVED'?'Optional review note':'Enter reason for this decision:');if(decision!=='APPROVED'&&!reason?.trim())return toast('A reason is required');k.status=decision;k.reason=reason||'';let u=userById(k.userId);u.kyc=decision;notify(u.id,'KYC status updated',`Your demo KYC status is now ${decision.replaceAll('_',' ')}.${reason?' Note: '+reason:''}`);audit('KYC decision: '+decision,k.id+' · '+u.name);saveDB();renderPage();toast('KYC decision saved')}
function adminRequest(id){let r=db.requests.find(x=>x.id===id);if(!r)return;modal('Request '+r.id,'Reply and update the service request status.',`<div class="kv"><span>User</span><b>${escapeHtml(r.user)}</b></div><div class="kv"><span>Category</span><b>${escapeHtml(r.category)}</b></div><div class="kv"><span>Subject</span><b>${escapeHtml(r.subject)}</b></div><div class="notice">${escapeHtml(r.message)}</div><div class="kv"><span>Current status</span>${statusBadge(r.status)}</div><div class="field"><label>Reply to user</label><textarea id="requestReply" placeholder="Write a clear response">${escapeHtml(r.reply||'')}</textarea></div><div class="field"><label>Update status</label><select id="requestStatus">${['SUBMITTED','ASSIGNED','IN_PROGRESS','WAITING_FOR_USER','ESCALATED','RESOLVED','CLOSED'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="form-actions"><button class="primary" id="saveRequest">Save response</button></div>`);$('#saveRequest').onclick=()=>{r.reply=$('#requestReply').value.trim();r.status=$('#requestStatus').value;notify(r.userId,'Support request updated',`${r.id} status: ${r.status.replaceAll('_',' ')}${r.reply?' — '+r.reply:''}`);audit('Support request updated',r.id+' · '+r.status);saveDB();$('#modalRoot').innerHTML='';renderPage();toast('Request updated and user notified')}}
function replyRequest(id){let r=db.requests.find(x=>x.id===id);modal('Reply to '+id,'Add a message to the support conversation.',`<div class="notice">${escapeHtml(r.reply||'No admin response yet.')}</div><div class="field"><label>Your message</label><textarea id="userReply" required placeholder="Type your reply"></textarea></div><div class="form-actions"><button class="primary" id="sendUserReply">Send reply</button></div>`);$('#sendUserReply').onclick=()=>{let msg=$('#userReply').value.trim();if(!msg)return toast('Enter a message');r.message+='\\nUser reply: '+msg;r.status='IN_PROGRESS';audit('User replied to request',r.id);saveDB();$('#modalRoot').innerHTML='';renderPage();toast('Reply added to demo request')}}
function subscribeFD(planId){const p=db.plans.find(x=>x.id===planId),u=currentUser();if(!p||p.status!=='ACTIVE')return toast('This plan is not available');modal(`Subscribe · ${p.days}-day FD`,'Review the daily rate, maturity estimate and demo terms before accepting.',`<div class="kv"><span>Plan / asset</span><b>${p.days} days · ${p.asset}</b></div><div class="kv"><span>Daily rate</span><b>${money(p.rate,3)}% per day</b></div><div class="kv"><span>Minimum / maximum</span><b>${money(p.min)} / ${money(p.max)} ${p.asset}</b></div><form id="fdSubForm"><div class="field"><label>Principal amount (${p.asset})</label><input name="amount" type="number" min="${p.min}" max="${p.max}" step="any" value="${p.min}" required></div><div class="notice warning" id="fdPreview">Estimated reward will be calculated here.</div><label style="display:flex;gap:9px;align-items:flex-start;font-size:11px;color:#aebbd0;margin-top:14px"><input type="checkbox" name="accept" required style="margin-top:2px"> I understand this is a simulated demo estimate, not a guaranteed return, and accept the displayed terms.</label><div class="form-actions"><button type="button" class="ghost" data-close-modal>Cancel</button><button class="primary" type="submit">Confirm demo subscription</button></div></form>`);let form=$('#fdSubForm'),amt=form.elements.amount,preview=()=>{let a=Number(amt.value)||0;$('#fdPreview').textContent=`Estimated simple reward: ${money(a*p.rate/100*p.days)} ${p.asset} · Estimated maturity value: ${money(a+a*p.rate/100*p.days)} ${p.asset}. Rate and terms snapshot saved at confirmation.`};amt.oninput=preview;preview();form.onsubmit=e=>{e.preventDefault();let amount=Number(amt.value);if(!form.elements.accept.checked)return toast('Accept the demo terms to continue');if(amount<p.min||amount>p.max)return toast('Amount is outside this plan limit');if((u.balances[p.asset]||0)<amount)return toast('Insufficient available '+p.asset+' balance');if(u.kyc!=='APPROVED')return toast('KYC approval is required for FD subscription in this demo');u.balances[p.asset]-=amount;u.locked=(u.locked||0)+amount;let start=new Date(),maturity=new Date(start.getTime()+p.days*86400000),reward=amount*p.rate/100*p.days;let f={id:shortId('FD'),userId:u.id,user:u.name,planId:p.id,days:p.days,asset:p.asset,amount,rate:p.rate,unit:'percent_per_day',reward,start:start.toISOString().slice(0,10),maturity:maturity.toISOString().slice(0,10),status:'ACTIVE',termsVersion:1};db.fds.unshift(f);notify(u.id,'FD subscription active',`${f.id}: ${p.days}-day demo contract created. Estimated reward ${money(reward)} ${p.asset}.`);audit('FD subscription created',f.id+' · '+amount+' '+p.asset);saveDB();$('#modalRoot').innerHTML='';renderPage();toast('FD subscription created in demo mode')}}
function planModal(id){let p=id?db.plans.find(x=>x.id===id):{id:shortId('FDPLAN'),days:10,rate:.1,unit:'percent',min:50,max:50000,status:'DRAFT',asset:'USDT'};modal(id?'Edit FD plan rate':'Configure FD plan','Daily rate unit: percentage per day. Editing creates a new demo terms version for future subscriptions only.',`<form id="planForm"><div class="field"><label>Plan ID</label><input name="id" value="${p.id}" required ${id?'readonly':''}></div><div class="field"><label>Duration</label><select name="days">${[10,20,30,60].map(d=>`<option ${p.days===d?'selected':''}>${d}</option>`).join('')}</select></div><div class="field"><label>Asset</label><select name="asset"><option ${p.asset==='USDT'?'selected':''}>USDT</option><option ${p.asset==='BTC'?'selected':''}>BTC</option><option ${p.asset==='ETH'?'selected':''}>ETH</option></select></div><div class="field"><label>Daily rate (% per day)</label><input name="rate" type="number" min="0" max="10" step="0.001" value="${p.rate}" required></div><div class="field"><label>Minimum principal</label><input name="min" type="number" min="0" step="any" value="${p.min}" required></div><div class="field"><label>Maximum principal</label><input name="max" type="number" min="0" step="any" value="${p.max}" required></div><div class="notice warning">Preview formula: principal × daily rate ÷ 100 × eligible days. Simple, non-compounding. Confirm reward funding and legal approval before any production launch.</div><div class="form-actions"><button type="button" class="ghost" data-close-modal>Cancel</button><button class="primary" type="submit">Save plan</button></div></form>`);$('#planForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),rate=Number(f.get('rate')),min=Number(f.get('min')),max=Number(f.get('max'));if(rate<0||min<0||max<min)return toast('Check rate and min/max values');let existing=db.plans.find(x=>x.id===p.id);if(existing){existing.days=Number(f.get('days'));existing.asset=f.get('asset');existing.rate=rate;existing.min=min;existing.max=max;existing.version=(existing.version||1)+1;audit('FD plan rate/terms updated',existing.id+' version '+existing.version)}else{db.plans.unshift({id:p.id,days:Number(f.get('days')),asset:f.get('asset'),rate,min,max,status:'ACTIVE',unit:'percent',version:1});audit('FD plan created',p.id)}saveDB();$('#modalRoot').innerHTML='';renderPage();toast('FD plan saved')}}
function togglePlan(id){let p=db.plans.find(x=>x.id===id);if(!p)return;p.status=p.status==='ACTIVE'?'PAUSED':'ACTIVE';audit('FD plan '+p.status.toLowerCase(),id);saveDB();renderPage();toast('Plan '+p.status.toLowerCase())}
function settleFD(id){let f=db.fds.find(x=>x.id===id);if(!f||f.status!=='ACTIVE')return toast('Contract is not active');let u=userById(f.userId);f.status='SETTLED';u.locked=Math.max(0,(u.locked||0)-f.amount);u.balances[f.asset]=(u.balances[f.asset]||0)+f.amount+f.reward;f.settledAt=today();notify(f.userId,'FD settlement completed',`${f.id}: principal and illustrative reward credited in demo ledger.`);audit('FD demo settlement',f.id+' · '+money(f.amount+f.reward));saveDB();renderPage();toast('FD settled in demo ledger')}
function init(){loadDB();$$('.login-tabs .tab').forEach(b=>b.onclick=()=>showLogin(b.dataset.login));$('#loginForm').onsubmit=e=>{e.preventDefault();let name=$('#loginName').value.trim().toLowerCase();if(loginRole==='admin'){if(name!=='admin@novax.demo')return toast('Use admin@novax.demo for admin demo');enterApp('admin')}else{let u=db.users.find(x=>x.email.toLowerCase()===name);if(!u)return toast('Use alex@novax.demo or select user login from admin');enterApp('user',u.id)}};showLogin('user')}
init();


// Visual-only simulated ticker: prices intentionally are not fetched from an exchange.
(function initDemoTicker(){
 const assets=[['tickerBTC',67248.20],['tickerETH',3482.16],['tickerSOL',182.74],['tickerBNB',602.83]];
 const fmt=n=>n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
 function tick(){assets.forEach(([id,base])=>{const el=document.getElementById(id);if(!el)return;const wave=(Math.random()-.49)*.0017;const current=Number(el.dataset.value||base);const next=current*(1+wave);el.dataset.value=String(next);el.textContent=fmt(next);el.classList.remove('price-flash');void el.offsetWidth;el.classList.add('price-flash')})}
 setInterval(tick,2600);
})();
